input.command:
bash /tmp/e2e/restart.sh >/dev/null 2>&1; sleep 2; cat > /tmp/e2e/shots.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({ executablePath: '/opt/pw-browsers/chromium-1194/chrome-linux/chrome' });
const errs=[];
for (const theme of ['light','dark']) {
  const ctx = await b.newContext({ viewport:{width:1360,height:860}, colorScheme: theme });
  const p = await ctx.newPage(); p.on('console',m=>m.type()==='error'&&errs.push(m.text())); p.on('pageerror',e=>errs.push(String(e)));
  await p.goto('http://localhost:3001/#/'); await p.waitForTimeout(1500);
  await p.screenshot({path:`/tmp/e2e/land-${theme}.png`});
  await p.evaluate(()=>window.scrollTo(0,1000)); await p.waitForTimeout(900);
  await p.screenshot({path:`/tmp/e2e/land2-${theme}.png`});
  await p.goto('http://localhost:3001/#/applications'); await p.waitForTimeout(800);
  await p.screenshot({path:`/tmp/e2e/apps-${theme}.png`});
  console.log(theme, await p.locator('.status').innerText());
}
const ctx = await b.newContext({ viewport:{width:1360,height:860}, colorScheme:'light' });
const p = await ctx.newPage(); await p.goto('http://localhost:3001/#/'); await p.waitForTimeout(800);
await p.getByLabel(/Switch to dark/).click(); await p.waitForTimeout(400);
console.log('theme after click', await p.evaluate(()=>document.documentElement.dataset.theme));
await p.reload(); await p.waitForTimeout(500);
console.log('persisted', await p.evaluate(()=>document.documentElement.dataset.theme));
await p.getByLabel('Open help').click(); await p.waitForTimeout(400);
await p.screenshot({path:'/tmp/e2e/help-dark.png'});
console.log('errors', errs);
await b.close();
EOF
cp /tmp/e2e/shots.mjs ./shots.tmp.mjs && node shots.tmp.mjs; rm shots.tmp.mjs

